class codigo_marcActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('codigo_marc', 'list');
  }

  public function executeList()
  {
    $this->marc_variable_docs = MarcVariableDocPeer::doSelect(new Criteria());
  }
  
  public function executeDatos()
  {
    
  }
  
  public function executeShow()
  {
    $this->marc_variable_doc = MarcVariableDocPeer::retrieveByPk($this->getRequestParameter('marcvariabledoc_id'));
    $this->forward404Unless($this->marc_variable_doc);
  }

  public function executeCreate()
  {
    $this->marc_variable_doc = new MarcVariableDoc();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
  	$respuesta = $this->getResponse();
  	$respuesta->addJavascript('ajax');
  	$respuesta->addJavascript('combo_doc'); 
    $marc_variable_doc = MarcVariableDocPeer::retrieveByPk($this->getRequestParameter('marcvariabledoc_id'));
    $this->codigo_seleccionado = intval(($marc_variable_doc->getMarc()->getCodigo() / 100));		
	
	$c = new Criteria();
	$c->add(MarcIndicadorPrimarioPeer::MARC_ID,$marc_variable_doc->getMarcId());
	$this->primer_indicador = MarcIndicadorPrimarioPeer::doSelect($c);
	
	$b = new Criteria();
	$b->add(MarcIndicadorSecundarioPeer::MARC_ID,$marc_variable_doc->getMarcId());
	$this->segundo_indicador = MarcIndicadorSecundarioPeer::doSelect($b);
	
	$a = new Criteria();
	$a->add(MarcSubcampoPeer::MARC_ID,$marc_variable_doc->getMarcId());
    $this->subcampos = MarcSubcampoPeer::doSelect($a);
		  	   			
	$this->lista_campos = array(
		0 => "0XX",		
		1 => "1XX",
		2 => "2XX",
		3 => "3XX",
		4 => "4XX",
		5 => "5XX",
		6 => "6XX",
		7 => "7XX",				
		8 => "8XX",		
		9 => "9XX",		
	  );
	$this->marc_variable_doc =  $marc_variable_doc; 
    $this->forward404Unless($this->marc_variable_doc);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('marcvariabledoc_id'))
    {
      $marc_variable_doc = new MarcVariableDoc();
    }
    else
    {
      $marc_variable_doc = MarcVariableDocPeer::retrieveByPk($this->getRequestParameter('marcvariabledoc_id'));     
      $this->forward404Unless($marc_variable_doc);
    }
    $cod = $this->getRequestParameter('codigo');
    $sub = $this->getRequestParameter('subcampo');
    $doc = $this->getRequestParameter('documentacion_id');
    
    $marc_variable_doc->setMarcvariabledocId($this->getRequestParameter('marcvariabledoc_id'));
    $marc_variable_doc->setMarcsubcampoId($sub);
    $marc_variable_doc->setMarcId($cod);
    $marc_variable_doc->setDocumentacionId($doc);
    //$marc_variable_doc->setMarcindicadorprimarioId($this->getRequestParameter('indicador1'));
    //$marc_variable_doc->setMarcindicadorsecundarioId($this->getRequestParameter('indicador2'));
    $marc_variable_doc->setValorVariable($this->getRequestParameter('valor_variable'));
            
    
	if($this->validarMarc($cod,$sub,$doc) != null && $this->getRequestParameter('marcvariabledoc_id') == ''){
	   return $this->redirect($this->getRequest()->getScriptName().'/documentacion_tecnica/marc?documentacion_id='.$doc.'&msg=1');	   	
	}    
    
    $marc_variable_doc->save();        
        
    $this->actualizarMarc($marc_variable_doc->getMarcvariabledocId());
    
    $documentacion = DocumentacionPeer::retrieveByPK($this->getRequestParameter('documentacion_id'));
    $documentacion->setFechaModificacion(date('Y-m-d'));
    $documentacion->save();
    return $this->redirect($this->getRequest()->getScriptName().'/codigo_marc/show?marcvariabledoc_id='.$marc_variable_doc->getMarcvariabledocId());
  }
  
  public function validarMarc($cod,$sub,$doc)
  {
  	/**************************************************************************************************/
  	$c =  new Criteria();
  	$c->add(MarcVariableDocPeer::DOCUMENTACION_ID,$doc);
  	$c->add(MarcVariableDocPeer::MARC_ID,$cod);
  	$c->add(MarcVariableDocPeer::MARCSUBCAMPO_ID,$sub);
  	$temp = MarcVariableDocPeer::doSelectOne($c);  	
  	/**************************************************************************************************/
  	return $temp;
  }
  
  public function actualizarMarc($id_variable)
  {  	
  	$marc_variable_doc = MarcVariableDocPeer::retrieveByPk($id_variable);
  	/**************************************************************************************************/
  	$c =  new Criteria();
  	$c->add(MarcVariableDocPeer::DOCUMENTACION_ID,$marc_variable_doc->getDocumentacionId());
  	$c->add(MarcVariableDocPeer::MARC_ID,$marc_variable_doc->getMarcId());
	$marc = MarcVariableDocPeer::doSelect($c);
	/**************************************************************************************************/
	foreach($marc as $temp){
		$marc_variable = MarcVariableDocPeer::retrieveByPk($temp->getMarcvariabledocId());
		$marc_variable->setMarcindicadorprimarioId($marc_variable_doc->getMarcindicadorprimarioId());
		$marc_variable->setMarcindicadorsecundarioId($marc_variable_doc->getMarcindicadorsecundarioId());
		$marc_variable->save();
	}
	/**************************************************************************************************/      
  }
  
  public function executeDelete()
  {
    $marc_variable_doc = MarcVariableDocPeer::retrieveByPk($this->getRequestParameter('marcvariabledoc_id'));

    $this->forward404Unless($marc_variable_doc);

    $marc_variable_doc->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/codigo_marc/list');
  }
}
